"""Remove only a named QA source generated by the production integration checks."""
import argparse
import re
import time

import httpx

from backend.store import db, MEDIA
from backend.vision_common import VISION
from backend.worker import sql, HTTP, ORION


def clean_source(source):
    if not re.fullmatch(r'qa-real-[a-zA-Z0-9-]+',source):
        raise ValueError('Se requiere el nombre exacto de una fuente qa-real-*.')
    shifts=list(db.real_shifts.find({'source_id':source}))
    shift_ids=[s['shift_id'] for s in shifts]
    iterations=list(db.real_iterations.find({'source_id':source}))
    iteration_ids=[i['iteration_id'] for i in iterations]
    jobs=list(db.vision_jobs.find({'shift_id':{'$in':shift_ids}}))
    db.real_jobs.update_many({'shift_id':{'$in':shift_ids}},{'$set':{'status':'cancelled'}})
    for job in jobs:
        db.vision_jobs.update_one({'_id':job['_id']},{'$set':{'cancel_requested':True,'deleted':True}})
        db.sessions.update_one({'_id':job['session_id']},{'$set':{'deleted':True,'status':'deleted','purged':False}})
    time.sleep(2)
    for shift_id in shift_ids:
        folder=MEDIA/'real'/str(shift_id)
        if folder.exists():
            for path in sorted(folder.rglob('*'),key=lambda p:len(p.parts),reverse=True):
                path.rmdir() if path.is_dir() else path.unlink()
            folder.rmdir()
        sql('DELETE FROM posture_real_raw WHERE shift_id=?',[shift_id])
        sql('DELETE FROM posture_raw WHERE shift_id=?',[shift_id])
        HTTP.delete(ORION+'/ngsi-ld/v1/entities/urn:ngsi-ld:WorkShift:'+str(shift_id))
    tables=sql("SELECT table_schema,table_name FROM information_schema.columns WHERE column_name='shiftid'")['rows']
    for schema,table in tables:
        if schema.replace('_','').isalnum() and table.replace('_','').isalnum() and table.startswith('et'):
            for sid in shift_ids:sql(f'DELETE FROM "{schema}"."{table}" WHERE shiftid=?',[sid])
    for iteration_id in iteration_ids:
        folder=VISION/'uploads'/('video-real-'+str(iteration_id))
        if folder.exists():
            for path in folder.iterdir():path.unlink()
            folder.rmdir()
        HTTP.delete(ORION+'/ngsi-ld/v1/entities/urn:ngsi-ld:WorkIteration:'+str(iteration_id))
    for job in jobs:
        folder=VISION/'jobs'/job['job_id']
        if folder.exists():
            for path in sorted(folder.rglob('*'),key=lambda p:len(p.parts),reverse=True):
                path.rmdir() if path.is_dir() else path.unlink()
            folder.rmdir()
        db.studies.delete_one({'_id':job['study_id']})
    for cell in {s['cell_id'] for s in shifts}:
        for origin in ('ros','server'):
            HTTP.delete(ORION+'/ngsi-ld/v1/entities/urn:ngsi-ld:ErgonomicObservation:'+cell+':'+origin)
        db.latest.delete_many({'_id':{'$regex':re.escape(':'+cell)+r'(:|$)'}})
        db.cells.delete_one({'_id':cell})
    for collection in ('real_shifts','real_iterations','real_samples','real_actions','real_assessments',
        'real_results','real_jobs','vision_assets','vision_results','vision_jobs','inbox','results','frames','alerts'):
        db[collection].delete_many({'shift_id':{'$in':shift_ids}})
    db.operators.delete_many({'hmi_source':source})
    print({'source':source,'removed_shifts':shift_ids,'removed_iterations':iteration_ids})


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--source',required=True)
    clean_source(parser.parse_args().source)
